import java.util.*;

class Solution {
    public List<String> tickTock(int n) {
        List<String> res = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            if (i % 15 == 0) res.add("TickTock");      // both 3 and 5: check first
            else if (i % 3 == 0) res.add("Tick");
            else if (i % 5 == 0) res.add("Tock");
            else res.add(String.valueOf(i));         // the number itself as text
        }
        return res;
    }
}

