class Solution:
    def tickTock(self, n: int) -> List[str]:
        out = []
        for i in range(1, n + 1):
            if i % 15 == 0: out.append("TickTock")
            elif i % 3 == 0: out.append("Tick")
            elif i % 5 == 0: out.append("Tock")
            else: out.append(str(i))
        return out

